-- Seed besar: order + rating_reviews, rating dihitung dari ulasan. Idempoten.
begin;
delete from public.rating_reviews; delete from public.orders;
select setval(pg_get_serial_sequence('public.orders','id'), (select max(id) from public.orders));
select setval(pg_get_serial_sequence('public.rating_reviews','id'), (select max(id) from public.rating_reviews));
update public.merchants m set rating_avg = coalesce(a.avg,0), rating_count = coalesce(a.cnt,0) from (select merchant_id, round(avg(rating)::numeric,2) avg, count(*) cnt from public.rating_reviews where merchant_id is not null group by merchant_id) a where m.id = a.merchant_id;
commit;